// Пины для планок ESP32-S3
const int ledPin = 48;   // Встроенный RGB/светодиод на GPIO48 (если не загорится, можно сменить на 2)
const int buttonPin = 0; // Кнопка BOOT на плате

void setup() {
  pinMode(ledPin, OUTPUT);
  pinMode(buttonPin, INPUT_PULLUP); // Подтягиваем кнопку к питанию
}

void loop() {
  // Считываем состояние кнопки (нажата = LOW, отпущена = HIGH)
  if (digitalRead(buttonPin) == LOW) {
    digitalWrite(ledPin, HIGH); // Включаем светодиод
  } else {
    digitalWrite(ledPin, LOW);  // Выключаем светодиод
  }
}
